contracts/AgentMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import { ERC721Holder } from "@openzeppelin/contracts/token/ERC721/utils/ERC721Holder.sol";
import { IERC721 } from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import { IIdentityRegistry } from "./interfaces/IIdentityRegistry.sol";
import { IAgentMarketplace } from "./interfaces/IAgentMarketplace.sol";

contract AgentMarketplace is IAgentMarketplace, ERC721Holder {
    using EnumerableSet for EnumerableSet.UintSet;

    address public owner;
    IIdentityRegistry public immutable identityRegistry;

    mapping(uint256 => Agent) public agents;
    uint256[] public allAgentIds;

    // EnumerableSet for efficient owner-based lookups
    mapping(address => EnumerableSet.UintSet) private _ownerAgents;

    uint256 public constant WAITING_PERIOD = 7 days; // Waiting period to transfer ownership.
    address public pendingOwner;
    uint256 public waitOwnerUntil; // Timestamp from which the pending owner can accept ownership.

    event AgentRegistered(uint256 indexed agentId, address indexed owner, uint256 price, bool payToAgentWallet);
    event AgentDeactivated(uint256 indexed agentId, uint256 time);
    event PriceUpdated(uint256 indexed agentId, uint256 oldPrice, uint256 newPrice, uint256 time);
    event AgentReactivated(uint256 indexed agentId, uint256 time);
    event OwnerTransferred(address indexed oldOwner, address indexed newOwner, uint256 time);
    event OwnershipTransferStarted(address indexed currentOwner, address indexed newOwner, uint256 waitUntil);
    event AgentTransferred(uint256 indexed agentId, address indexed from, address indexed to);
    event PaymentDestinationUpdated(uint256 indexed agentId, bool payToAgentWallet);
    event NonceIncremented(uint256 indexed agentId, uint256 newNonce);

    error ZeroPrice();
    error EmptyURI();
    error AgentNotFoundInMarketplace();
    error ZeroAddress();
    error NotOwnerOfAgent();
    error AlreadyDeactivated();
    error SamePrice();
    error AlreadyActive();
    error InvalidPage();
    error NotOwner();
    error SameOwner();
    error SamePaymentDestination();
    error WaitingPeriodNotOver();

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor(address _identityRegistry) {
        if (_identityRegistry == address(0)) revert ZeroAddress();
        identityRegistry = IIdentityRegistry(_identityRegistry);
        owner = msg.sender;
    }

    // slither-disable-start reentrancy-benign,reentrancy-events
    function register(uint256 price, string memory agentURI, bool payToAgentWallet) external returns (uint256 agentId) {
        //cannot be <0 as it is uint and in this version of Solidity it would revert negative inputs as uints
        if (price == 0) revert ZeroPrice();
        if (bytes(agentURI).length == 0) revert EmptyURI();
        agentId = identityRegistry.register(agentURI);

        agents[agentId] = Agent({
            owner: msg.sender,
            agentId: agentId,
            price: price,
            nonce: 0,
            payToAgentWallet: payToAgentWallet,
            active: true
        });
        allAgentIds.push(agentId);
        // slither-disable-next-line unused-return
        _ownerAgents[msg.sender].add(agentId);
        emit AgentRegistered(agentId, msg.sender, price, payToAgentWallet);

        //As we are the owner currently we have to transfer the ownership to the msg.sender
        identityRegistry.safeTransferFrom(address(this), msg.sender, agentId);
    }

    // Register an existing agent by ID
    function register(uint256 price, uint256 agentId, bool payToAgentWallet) external returns (uint256) {
        // Ensure not already registered
        if (agents[agentId].owner != address(0)) revert AlreadyActive();
        // Ensure caller owns the agent token
        if (identityRegistry.ownerOf(agentId) != msg.sender) revert NotOwnerOfAgent();
        if (price == 0) revert ZeroPrice();
        agents[agentId] = Agent({
            owner: msg.sender,
            agentId: agentId,
            price: price,
            nonce: 0,
            payToAgentWallet: payToAgentWallet,
            active: true
        });
        allAgentIds.push(agentId);
        // slither-disable-next-line unused-return
        _ownerAgents[msg.sender].add(agentId);
        emit AgentRegistered(agentId, msg.sender, price, payToAgentWallet);
        return agentId;
    }

    function transferAgent(uint256 agentId, address newOwner) external {
        if (agents[agentId].owner == address(0)) revert AgentNotFoundInMarketplace();
        if (newOwner == address(0)) revert ZeroAddress();

        address currentOwner = identityRegistry.ownerOf(agentId);

        if (msg.sender != currentOwner) revert NotOwnerOfAgent();
        if (currentOwner == newOwner) revert SameOwner();

        agents[agentId].owner = newOwner;
        // slither-disable-next-line unused-return
        _ownerAgents[currentOwner].remove(agentId);
        // slither-disable-next-line unused-return
        _ownerAgents[newOwner].add(agentId);

        emit AgentTransferred(agentId, currentOwner, newOwner);

        identityRegistry.safeTransferFrom(currentOwner, newOwner, agentId);
    }

    function syncAgentOwnership(uint256 agentId) external {
        if (agents[agentId].owner == address(0)) revert AgentNotFoundInMarketplace();

        address currentOwner = identityRegistry.ownerOf(agentId);
        address marketplaceRecordedOwner = agents[agentId].owner;

        if (currentOwner == marketplaceRecordedOwner) revert SameOwner();

        agents[agentId].owner = currentOwner;
        // slither-disable-next-line unused-return
        _ownerAgents[marketplaceRecordedOwner].remove(agentId);
        // slither-disable-next-line unused-return
        _ownerAgents[currentOwner].add(agentId);

        emit AgentTransferred(agentId, marketplaceRecordedOwner, currentOwner);
    }

    /// @notice Returns the list of agents owned by a specific address.
    function getAgentsByOwner(address agentOwner) external view returns (AgentFullDetails[] memory) {
        uint256[] memory agentIds = _ownerAgents[agentOwner].values();
        AgentFullDetails[] memory details = new AgentFullDetails[](agentIds.length);
        for (uint256 i = 0; i < agentIds.length; i++) {
            details[i] = getAgentFullDetails(agentIds[i]);
        }
        return details;
    }

    // slither-disable-end reentrancy-benign,reentrancy-events

    function deactivateAgent(uint256 agentId) external {
        Agent storage agent = agents[agentId];
        if (agent.owner == address(0)) revert AgentNotFoundInMarketplace();
        if (identityRegistry.ownerOf(agentId) != msg.sender) revert NotOwnerOfAgent();
        if (!agent.active) revert AlreadyDeactivated();
        agent.active = false;
        emit AgentDeactivated(agentId, block.timestamp);
    }

    function reactivateAgent(uint256 agentId) external {
        Agent storage agent = agents[agentId];
        if (agent.owner == address(0)) revert AgentNotFoundInMarketplace();
        if (identityRegistry.ownerOf(agentId) != msg.sender) revert NotOwnerOfAgent();
        if (agent.active) revert AlreadyActive();
        agent.active = true;
        emit AgentReactivated(agentId, block.timestamp);
    }

    function updatePrice(uint256 agentId, uint256 newPrice) external {
        Agent storage agent = agents[agentId];
        if (agent.owner == address(0)) revert AgentNotFoundInMarketplace();
        if (identityRegistry.ownerOf(agentId) != msg.sender) revert NotOwnerOfAgent();
        if (newPrice == 0) revert ZeroPrice();
        if (newPrice == agent.price) revert SamePrice();
        emit PriceUpdated(agentId, agent.price, newPrice, block.timestamp);
        agent.price = newPrice;
    }

    function setPaymentDestination(uint256 agentId, bool newPayToAgentWallet) external {
        Agent storage agent = agents[agentId];
        if (agent.owner == address(0)) revert AgentNotFoundInMarketplace();
        if (identityRegistry.ownerOf(agentId) != msg.sender) revert NotOwnerOfAgent();
        if (agent.payToAgentWallet == newPayToAgentWallet) revert SamePaymentDestination();
        agent.payToAgentWallet = newPayToAgentWallet;
        emit PaymentDestinationUpdated(agentId, newPayToAgentWallet);
    }

    /// @notice Increments the agent's nonce, rotating its derived API key.
    /// @dev Only the current agent owner (per the IdentityRegistry) may call this.
    function incrementNonce(uint256 agentId) external {
        if (agents[agentId].owner == address(0)) revert AgentNotFoundInMarketplace();
        if (identityRegistry.ownerOf(agentId) != msg.sender) revert NotOwnerOfAgent();
        agents[agentId].nonce++;
        emit NonceIncremented(agentId, agents[agentId].nonce);
    }

    function getAgent(uint256 agentId) public view returns (Agent memory) {
        if (agents[agentId].owner == address(0)) revert AgentNotFoundInMarketplace();
        return agents[agentId];
    }

    // slither-disable-next-line calls-loop
    function getAgentFullDetails(uint256 agentId) public view returns (AgentFullDetails memory) {
        Agent memory agent = getAgent(agentId);

        address agentOwner = address(0);
        try identityRegistry.ownerOf(agentId) returns (address o) {
            agentOwner = o;
        } catch {
            // Token burned or non-existent in the registry — return inactive, zeroed-out record
            agent.active = false;
            return AgentFullDetails(agent, address(0), "");
        }

        string memory uri = "";
        try identityRegistry.tokenURI(agentId) returns (string memory u) {
            uri = u;
        } catch {
            uri = "";
        }

        return AgentFullDetails(agent, agentOwner, uri);
    }

    function getAgentsFullPaginated(uint256 page, uint256 count) external view returns (AgentFullDetails[] memory) {
        if (page == 0) revert InvalidPage();
        if (count == 0) return new AgentFullDetails[](0);

        uint256 totalAgents = allAgentIds.length;
        uint256 startIndex = (page - 1) * count;

        if (startIndex >= totalAgents) revert InvalidPage();

        uint256 endIndex = startIndex + count;
        if (endIndex > totalAgents) {
            endIndex = totalAgents;
        }

        uint256 actualCount = endIndex - startIndex;
        AgentFullDetails[] memory res = new AgentFullDetails[](actualCount);

        for (uint256 i = 0; i < actualCount; i++) {
            res[i] = getAgentFullDetails(allAgentIds[startIndex + i]);
        }

        return res;
    }

    //To transfer ownership of the marketplace there is a two-step verification. First the actual owner approves a new address and then this new//
    //address has to call acceptOwnership. this prevents commiting mistakes, and brings extra security in a crticial process. //

    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == owner) revert SameOwner();
        pendingOwner = newOwner;
        waitOwnerUntil = block.timestamp + WAITING_PERIOD;
        emit OwnershipTransferStarted(owner, newOwner, waitOwnerUntil);
    }

    function acceptOwnership() external {
        if (msg.sender != pendingOwner) revert NotOwner();
        // slither-disable-next-line timestamp
        if (block.timestamp < waitOwnerUntil) revert WaitingPeriodNotOver();
        emit OwnerTransferred(owner, pendingOwner, block.timestamp);
        owner = pendingOwner;
        pendingOwner = address(0);
    }

    function rescueERC721(address nftContract, uint256 tokenId) external onlyOwner {
        IERC721(nftContract).safeTransferFrom(address(this), msg.sender, tokenId);
    }

    function rescueERC20(address tokenContract, uint256 amount) external onlyOwner {
        require(IERC20(tokenContract).transfer(msg.sender, amount));
    }
}

contracts/interfaces/IAgentMarketplace.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import { IIdentityRegistry } from "./IIdentityRegistry.sol";

interface IAgentMarketplace {
    struct Agent {
        address owner;
        uint256 agentId;
        uint256 price;
        uint256 nonce;
        bool payToAgentWallet;
        bool active;
    }

    struct AgentFullDetails {
        Agent agent;
        address owner;
        string uri;
    }

    function getAgent(uint256) external view returns (Agent memory);
    function getAgentFullDetails(uint256) external view returns (AgentFullDetails memory);
    function getAgentsFullPaginated(uint256 page, uint256 count) external view returns (AgentFullDetails[] memory);
    function getAgentsByOwner(address agentOwner) external view returns (AgentFullDetails[] memory);
    function identityRegistry() external view returns (IIdentityRegistry);
}

contracts/interfaces/IIdentityRegistry.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

import { IERC721Metadata } from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Metadata.sol";

/**
 * @title IIdentityRegistry
 * @dev Interface for the ERC-8004 Identity Registry.
 * It manages agent identities as portable and transferable ERC-721 tokens.
 */
interface IIdentityRegistry is IERC721Metadata {
    /**
     * @dev Metadata structure as defined in the source code.
     */
    struct MetadataEntry {
        string metadataKey;
        bytes metadataValue;
    }

    // --- Events ---

    event AgentRegistered(uint256 indexed agentId, address indexed owner);
    event AgentURIUpdated(uint256 indexed agentId, string uri);
    event MetadataUpdated(uint256 indexed agentId, string indexed key, bytes value);
    event AgentWalletUpdated(uint256 indexed agentId, address indexed newWallet);

    // --- Registration Methods (The 3 Variants) ---

    /**
     * @notice Basic registration. Mints an agent NFT to the caller.
     */
    function register() external returns (uint256 agentId);

    /**
     * @notice Registers an agent and sets the initial agentURI (tokenURI).
     * @param uri The URI pointing to the agent's registration JSON file.
     */
    function register(string calldata uri) external returns (uint256 agentId);

    /**
     * @notice Registers an agent, sets the URI, and initializes on-chain metadata.
     * @param uri The initial registration file URI.
     * @param metadata Initial metadata entries for the agent.
     */
    function register(string calldata uri, MetadataEntry[] calldata metadata) external returns (uint256 agentId);

    // --- Agent URI Management ---

    /**
     * @notice Updates the agent's registration file URI (tokenURI).
     */
    function setAgentURI(uint256 agentId, string calldata uri) external;

    // --- Metadata Management ---

    /**
     * @notice Retrieves the raw bytes value of a metadata key for an agent.
     */
    function getMetadata(uint256 agentId, string calldata metadataKey) external view returns (bytes memory);

    /**
     * @notice Sets a single on-chain metadata value.
     */
    function setMetadata(uint256 agentId, string calldata metadataKey, bytes calldata metadataValue) external;

    // --- Agent Wallet Management ---

    /**
     * @notice Gets the verified wallet address associated with the agent.
     */
    function getAgentWallet(uint256 agentId) external view returns (address);

    /**
     * @notice Updates the verified wallet using an EIP-712 or ERC-1271 signature.
     * @dev This wallet is cleared automatically upon NFT transfer.
     */
    function setAgentWallet(uint256 agentId, address newWallet, uint256 expiry, bytes calldata signature) external;

    /**
     * @notice Manually removes the verified wallet association.
     */
    function unsetAgentWallet(uint256 agentId) external;

    /**
     * @notice Returns the EIP-712 domain separator information.
     */
    function eip712Domain()
        external
        view
        returns (
            bytes1 fields,
            string memory name,
            string memory version,
            uint256 chainId,
            address verifyingContract,
            bytes32 salt,
            uint256[] memory extensions
        );
}

contracts/interfaces/IReputationRegistry.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.35;

/**
 * @title IReputationRegistry
 * @dev Interface for the ERC-8004 Reputation Registry.
 * It manages trust signals for agents as signed fixed-point numbers.
 */
interface IReputationRegistry {
    // --- Events ---

    /**
     * @notice Emitted when feedback is recorded for an agent.
     */
    event FeedbackGiven(
        uint256 indexed agentId,
        address indexed client,
        int128 value,
        uint8 valueDecimals,
        string tag1,
        string tag2,
        string endpoint
    );

    /**
     * @notice Emitted when a client revokes their previously given feedback [3].
     */
    event FeedbackRevoked(uint256 indexed agentId, address indexed client, uint256 feedbackIndex);

    /**
     * @notice Emitted when a response is appended to an existing feedback entry [3].
     */
    event ResponseAppended(
        uint256 indexed agentId,
        address indexed client,
        uint256 feedbackIndex,
        address responder,
        string responseURI
    );

    // --- Core Functions ---

    /**
     * @notice Records a feedback signal for an agent with 8 parameters.
     * @dev Prevents self-feedback by checking the agent owner/operator via Identity Registry.
     * @param agentId The identifier of the agent receiving feedback.
     * @param value The numeric value of the signal (int128).
     * @param valueDecimals The precision of the value (0-18).
     * @param tag1 Primary categorization tag (e.g., "mcp", "performance").
     * @param tag2 Secondary categorization tag (e.g., "accuracy", "latency").
     * @param endpoint The specific agent endpoint or service URI related to this feedback.
     * @param feedbackURI URI pointing to a verbose off-chain JSON payload.
     * @param feedbackHash Hash of the off-chain payload for integrity.
     */
    function giveFeedback(
        uint256 agentId,
        int128 value,
        uint8 valueDecimals,
        string calldata tag1,
        string calldata tag2,
        string calldata endpoint,
        string calldata feedbackURI,
        bytes32 feedbackHash
    ) external;

    /**
     * @notice Allows a client to revoke their feedback [3].
     * @param agentId The identifier of the agent.
     * @param feedbackIndex The index of the feedback to revoke.
     */
    function revokeFeedback(uint256 agentId, uint256 feedbackIndex) external;

    /**
     * @notice Appends a response (e.g., from the agent or a third party) to feedback [3].
     * @param agentId The identifier of the agent.
     * @param client The address of the original feedback provider.
     * @param feedbackIndex The index of the feedback entry.
     * @param responseURI URI for the response context.
     * @param responseHash Hash of the response content.
     */
    function appendResponse(
        uint256 agentId,
        address client,
        uint256 feedbackIndex,
        string calldata responseURI,
        bytes32 responseHash
    ) external;

    // --- Read & Aggregation Functions [2] ---

    /**
     * @notice Retrieves a specific feedback entry.
     */
    function readFeedback(
        uint256 agentId,
        address client,
        uint256 feedbackIndex
    )
        external
        view
        returns (
            int128 value,
            uint8 valueDecimals,
            string memory tag1,
            string memory tag2,
            string memory endpoint,
            string memory feedbackURI,
            bytes32 feedbackHash,
            bool revoked
        );

    /**
     * @notice Returns all feedback for an agent, filtered by clients and tags.
     */
    function readAllFeedback(
        uint256 agentId,
        address[] calldata clientAddresses,
        string calldata tag1,
        string calldata tag2,
        bool includeRevoked
    ) external view returns (bytes[] memory feedbacks);

    /**
     * @notice Returns a summary of feedback signals for an agent.
     * @dev Requires clientAddresses to mitigate Sybil/spam risks.
     * @return count Total number of feedbacks found.
     * @return summaryValue Aggregated signal value.
     * @return summaryValueDecimals Precision of the aggregated value.
     */
    function getSummary(
        uint256 agentId,
        address[] calldata clientAddresses,
        string calldata tag1,
        string calldata tag2
    ) external view returns (uint256 count, int128 summaryValue, uint8 summaryValueDecimals);
}

